  "data_file": "beauty and the labor market.csv",
  "analysis_methods": [
    {
      "id": 64,
      "question": "Calculate the mean and standard deviation of the wage column.",
      "constraints": "The mean and standard deviation of the wage should be calculated using pandas' `mean()` and `std()` methods respectively. Do not apply any transformations, filtering or alteration to the wage data.",
      "format": "@mean_wage[mean_value] @std_wage[std_value] where \"mean_value\" and \"std_value\" are numbers with up to two decimal places."
    },
    {
      "id": 66,
      "question": "Calculate the correlation between the wage column and the exper column.",
      "constraints": "Calculate the Pearson correlation coefficient (r) to assess the strength and direction of the linear relationship between wage and the exper. Assess the significance of the correlation using a two-tailed test with a significance level (alpha) of 0.05. Report the p-value associated with the correlation test. Consider the relationship to be linear if the p-value is less than 0.05 and the absolute value of r is greater than or equal to 0.5. Consider the relationship to be nonlinear if the p-value is less than 0.05 and the absolute value of r is less than 0.5. If the p-value is greater than or equal to 0.05, report that there is no significant correlation.",
      "format": "@correlation_coefficient[r_value] @p_value[p_value] @relationship_type[relationship_type] where \"r_value\" is a number between -1 and 1, rounded to two decimal places. where \"p_value\" is a number between 0 and 1, rounded to four decimal places. where \"relationship_type\" is a string that can either be \"linear\", \"nonlinear\", or \"none\" based on the conditions specified in the constraints."
    },
    {
      "id": 69,
      "question": "Perform feature engineering by creating a new feature called \"experience_score\" that is calculated by multiplying the exper column with the looks column. Then, calculate the Pearson correlation coefficient between the \"experience_score\" feature and the wage column.",
      "constraints": "Create \"experience_score\" by directly multiplying values of exper and looks column. Calculate Pearson correlation coefficient between the new feature \"experience_score\" and wage. Correlation should be calculated up to three decimal places.",
      "format": "@correlation[correlation] where \"correlation\" is a number representing the correlation coefficient, rounded to three decimal places."
    },
    {
      "id": 70,
      "question": "Perform machine learning by training a linear regression model to predict the wage based on the features exper, looks, union, goodhlth, black, female, married, south, bigcity, smllcity, service, and educ. Use the Root Mean Squared Error (RMSE) for evaluating the model's performance.",
      "constraints": "Perform the machine learning task using the sklearn library's LinearRegression() function. Split the dataset into a 70% training set and a 30% test set. Set the random seed to 42 for reproducibility of the results. Calculate the RMSE on the test set.",
      "format": "@RMSE[RMSE_value] where \"RMSE_value\" is a number rounded to two decimal places."
    }
  ],
  "format_scope": "Original format fields specify result identities and numeric precision. The current deliverable is a natural-language report; the upstream @field[value] syntax is not required."
}

